CREATE OR REPLACE FUNCTION public.add_post_comment(p_post_id uuid, p_body text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_owner uuid;
  v_can_view boolean;
begin
  if p_body is null or btrim(p_body) = '' then
    return;
  end if;

  select owner_user_id into v_owner
  from public.posts
  where id = p_post_id;

  if v_owner is null then
    raise exception 'post not found';
  end if;

  -- canonical can-view-post: owner OR approved follower of owner
  select (
    (v_owner = auth.uid())
    or exists (
      select 1
      from public.follows f
      where (f.follower_user_id = auth.uid())
        and (f.followed_user_id = v_owner)
        and (f.status = 'approved'::text)
    )
  ) into v_can_view;

  if not v_can_view then
    raise exception 'not permitted';
  end if;

  -- non-owner only
  if auth.uid() = v_owner then
    raise exception 'owner must reply via reply_to_commenter/respond_to_commenters';
  end if;

  insert into public.post_comments (post_id, owner_user_id, author_user_id, recipient_user_id, body)
  values (p_post_id, v_owner, auth.uid(), v_owner, p_body);
end;
$function$

CREATE OR REPLACE FUNCTION public.cleanup_post_attachments_on_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  item jsonb;
  v_bucket text;
  v_path text;
begin
  -- If no attachments, nothing to do
  if OLD.attachments is null then
    return OLD;
  end if;

  -- Loop through attachments JSON array
  for item in
    select * from jsonb_array_elements(OLD.attachments)
  loop
    v_bucket := item->>'bucket';
    v_path   := item->>'path';

    if v_bucket = 'attachments' and v_path is not null then
      delete from storage.objects
      where bucket_id = v_bucket
        and name = v_path;
    end if;
  end loop;

  return OLD;
end;
$function$

CREATE OR REPLACE FUNCTION public.cleanup_post_attachments_on_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  old_item jsonb;
  v_bucket text;
  v_path text;
begin
  -- If attachments didn't change, do nothing
  if OLD.attachments is not distinct from NEW.attachments then
    return NEW;
  end if;

  -- Loop through OLD attachments
  for old_item in
    select * from jsonb_array_elements(coalesce(OLD.attachments, '[]'::jsonb))
  loop
    v_bucket := old_item->>'bucket';
    v_path   := old_item->>'path';

    -- If this old attachment is NOT present in NEW.attachments → delete it
    if not exists (
      select 1
      from jsonb_array_elements(coalesce(NEW.attachments, '[]'::jsonb)) as new_item
      where new_item->>'bucket' = v_bucket
        and new_item->>'path' = v_path
    )
    then
      if v_bucket = 'attachments' and v_path is not null then
        delete from storage.objects
        where bucket_id = v_bucket
          and name = v_path;
      end if;
    end if;

  end loop;

  return NEW;
end;
$function$

CREATE OR REPLACE FUNCTION public.reply_to_commenter(p_post_id uuid, p_recipient_user_id uuid, p_body text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_owner uuid;
  v_ok boolean;
begin
  if p_body is null or btrim(p_body) = '' then
    return;
  end if;

  select owner_user_id into v_owner
  from public.posts
  where id = p_post_id;

  if v_owner is null then
    raise exception 'post not found';
  end if;

  if auth.uid() <> v_owner then
    raise exception 'owner only';
  end if;

  select exists (
    select 1
    from public.post_comments c
    where c.post_id = p_post_id
      and c.owner_user_id = v_owner
      and c.author_user_id = p_recipient_user_id
      and c.author_user_id <> v_owner
  ) into v_ok;

  if not v_ok then
    raise exception 'invalid recipient';
  end if;

  insert into public.post_comments (post_id, owner_user_id, author_user_id, recipient_user_id, body)
  values (p_post_id, v_owner, v_owner, p_recipient_user_id, p_body);
end;
$function$

CREATE OR REPLACE FUNCTION public.respond_to_commenters(p_post_id uuid, p_body text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_owner uuid;
begin
  if p_body is null or btrim(p_body) = '' then
    return;
  end if;

  select owner_user_id into v_owner
  from public.posts
  where id = p_post_id;

  if v_owner is null then
    raise exception 'post not found';
  end if;

  if auth.uid() <> v_owner then
    raise exception 'owner only';
  end if;

  insert into public.post_comments (post_id, owner_user_id, author_user_id, recipient_user_id, body)
  select
    p_post_id,
    v_owner,
    v_owner,
    c.author_user_id,
    p_body
  from (
    select distinct c.author_user_id
    from public.post_comments c
    where c.post_id = p_post_id
      and c.owner_user_id = v_owner
      and c.author_user_id <> v_owner
  ) c;
end;
$function$

CREATE OR REPLACE FUNCTION public.sign_attachment_rpc(p_post_id uuid, p_attachment_index integer, p_expires_in integer DEFAULT 600)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_viewer uuid;
  v_owner uuid;
  v_session_id uuid;
  v_attachments jsonb;
  v_elem jsonb;
  v_bucket text;
  v_path text;
  v_allowed boolean := false;
  v_prefix text;
  v_url text;
begin
  v_viewer := auth.uid();
  if v_viewer is null then
    return jsonb_build_object('error','unauthenticated');
  end if;

  if p_attachment_index is null or p_attachment_index < 0 then
    return jsonb_build_object('error','bad_request');
  end if;

  select owner_user_id, session_id, attachments
    into v_owner, v_session_id, v_attachments
  from public.posts
  where id = p_post_id;

  if v_owner is null then
    return jsonb_build_object('error','forbidden');
  end if;

  -- Permission: owner OR approved follower
  if v_viewer = v_owner then
    v_allowed := true;
  else
    v_allowed := exists (
      select 1
      from public.follows f
      where f.follower_user_id = v_viewer
        and f.followed_user_id = v_owner
        and f.status = 'approved'
    );
  end if;

  if not v_allowed then
    return jsonb_build_object('error','forbidden');
  end if;

  -- Attachments array and bounds
  if jsonb_typeof(v_attachments) <> 'array' then
    return jsonb_build_object('error','forbidden');
  end if;

  if p_attachment_index >= jsonb_array_length(v_attachments) then
    return jsonb_build_object('error','forbidden');
  end if;

  v_elem := v_attachments -> p_attachment_index;
  v_bucket := v_elem ->> 'bucket';
  v_path := v_elem ->> 'path';

  if v_bucket is null or v_path is null then
    return jsonb_build_object('error','forbidden');
  end if;

  if v_session_id is null then
    return jsonb_build_object('error','forbidden');
  end if;

  -- Hardening: case-insensitive match for users/<owner>/<session_id>/... OR debug/
  v_prefix := 'users/' || v_owner::text || '/' || v_session_id::text || '/';

  if left(lower(v_path), length(v_prefix)) <> lower(v_prefix) and left(v_path, 6) <> 'debug/' then
    return jsonb_build_object('error','forbidden');
  end if;

  -- Sign URL (short TTL)
  select (storage.create_signed_url(v_bucket, v_path, p_expires_in)).signed_url
    into v_url;

  if v_url is null then
    return jsonb_build_object('error','forbidden');
  end if;

  return jsonb_build_object(
    'signed_url', v_url,
    'expires_in', p_expires_in
  );
end;
$function$
